(880, 181, '_elementor_data', '[{\"id\":\"135cdd8\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"hover_parallax\":[{\"layer_position_vr\":{\"unit\":\"%\",\"size\":30},\"layer_position_hr\":{\"unit\":\"%\",\"size\":40},\"_id\":\"57549ae\"},{\"layer_position_vr\":{\"unit\":\"%\",\"size\":60},\"layer_position_hr\":{\"unit\":\"%\",\"size\":20},\"_id\":\"494e3a1\"}]},\"elements\":[{\"id\":\"c1233d5\",\"elType\":\"widget\",\"settings\":{\"slider_items\":[{\"slider_item_title\":\"ExamHive24\",\"slider_item_sub_title\":\"We always be your side\",\"slider_item_description\":\"ExamHive24 is a smart and user-friendly online examination platform designed to make learning and assessment seamless. It offers secure, efficient, and interactive tools for students, teachers, and institutions to conduct tests, quizzes, and exams with ease. With features like automated grading, detailed analytics, customizable question banks, and real-time monitoring, ExamHive24 ensures a smooth examination experience.\",\"slider_item_btn_text_1\":\"Learn More\",\"slider_item_btn_text_2\":\"All Exams\",\"slider_item_overlay_bg\":\"#2726409C\",\"_id\":\"a3930ad\",\"slider_item_bg_image\":{\"url\":\"http:\\/\\/localhost\\/ExamHive24\\/wp-content\\/uploads\\/2025\\/08\\/istockphoto-1443628665-612x612-1.jpg\",\"id\":64,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"slider_item_blend_mode\":\"multiply\"},{\"slider_item_title\":\"Our Achievement\",\"slider_item_sub_title\":\"Be with us\",\"slider_item_description\":\"Ucessfully conducted 1000+ online exams with secure and reliable performance. Built a question bank of 10,000+ questions across multiple subjects and difficulty levels.\\n\\nHelped 500+ students and professionals improve their knowledge through practice tests. Integrated smart analytics & instant grading, reducing evaluation time by 80%. Recognized as a trusted e-learning and exam platform by educators and institutions.\",\"slider_item_btn_text_1\":\"Privacy Policy\",\"slider_item_btn_text_2\":\"Terms and Conditions\",\"slider_item_overlay_bg\":\"#1E1420AB\",\"_id\":\"5947f47\",\"slider_item_bg_image\":{\"url\":\"http:\\/\\/localhost\\/ExamHive24\\/wp-content\\/uploads\\/2025\\/08\\/pexels-cottonbro-4861373.jpg\",\"id\":71,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"slider_item_blend_mode\":\"multiply\"},{\"slider_item_title\":\"Our Success\",\"slider_item_sub_title\":\"Success is our pride\",\"slider_item_description\":\"Transforming exams into effortless learning\\u2014ExamHive24 drives success for students and educators alike! Smarter tests, instant results, real success\\u2014ExamHive24 makes learning count!\\\"\\n\\n\\\"From classrooms to cloud\\u2014ExamHive powers the future of online assessments! Secure, simple, and smart\\u2014ExamHive24 turns every test into a success story!\\n\\n\",\"slider_item_btn_text_1\":\"About\",\"slider_item_btn_text_2\":\"Shop\",\"slider_item_overlay_bg\":\"#38292994\",\"_id\":\"52c6d35\",\"slider_item_bg_image\":{\"url\":\"http:\\/\\/localhost\\/ExamHive24\\/wp-content\\/uploads\\/2025\\/08\\/stationery-and-word-exam-made-of-letters-on-wooden-background-education-college-school-stress-university-student-studying-concept-flat-lay-or-top-view-T1TXR8.jpg\",\"id\":74,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"slider_item_blend_mode\":\"multiply\",\"slider_item_btn_url_1\":{\"url\":\"http:\\/\\/localhost\\/ExamHive24\\/about\\/\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"slider_item_btn_url_2\":{\"url\":\"http:\\/\\/localhost\\/ExamHive24\\/shop\\/\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}}],\"slider_content_hr\":\"left\",\"slider_content_align\":\"left\",\"__globals__\":{\"slider_title_typography_typography\":\"globals\\/typography?id=primary\",\"slider_description_typography_typograph